import { useEffect, useId, useMemo, useRef, useState, startTransition, type CSSProperties } from "react"
import { addPropertyControls, ControlType } from "framer"
import { motion, type Transition as MotionTransition } from "framer-motion"

type Point = { x: number; y: number }

type RollingTextProps = {
    text: string
    transition: MotionTransition
    stagger: number
    reverse: boolean
    font: any
    color: string
    hoverColor: string
    background: {
        enabled: boolean
        backgroundColor: string
        hoverBackgroundColor: string
        hoverTransition: number
        hoverRadius: string
    }
    shape: {
        enabled: boolean
        mode: "string" | "points"
        polygon: string
        hoverPolygon: string
        points: Point[]
        hoverPoints: Point[]
        roundedCorners: boolean
        cornerRadius: number
        transition: number
    }
    radius: string
    textTransform: "none" | "uppercase" | "lowercase" | "capitalize"
    padding: string
    gap: number
    textAlign: "left" | "center" | "right"
    style?: CSSProperties
}

/**
 * @framerIntrinsicWidth 200
 * @framerIntrinsicHeight 50
 *
 * @framerSupportedLayoutWidth any-prefer-fixed
 * @framerSupportedLayoutHeight any-prefer-fixed
 */
function clamp(n: number, min: number, max: number) {
    return Math.max(min, Math.min(max, n))
}

function parsePolygonToPoints(polygon: string): Point[] {
    const raw = String(polygon || "")
        .trim()
        .replace(/^polygon\(/i, "")
        .replace(/\)$/, "")

    const parts = raw
        .split(/,(?![^()]*\))/)
        .map((p) => p.trim())
        .filter(Boolean)

    const pts: Point[] = []
    for (const part of parts) {
        const match = part.match(/(-?\d*\.?\d+)%?\s+(-?\d*\.?\d+)%?/i)
        if (!match) continue
        const x = clamp(parseFloat(match[1]), 0, 100)
        const y = clamp(parseFloat(match[2]), 0, 100)
        pts.push({ x, y })
    }

    return pts
}

function pointsToPolygonString(points: Point[]) {
    const pts = (points || []).filter(Boolean)
    if (pts.length < 3) return "polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%)"
    return `polygon(${pts.map((p) => `${clamp(p.x, 0, 100)}% ${clamp(p.y, 0, 100)}%`).join(", ")})`
}

function dist(a: Point, b: Point) {
    const dx = b.x - a.x
    const dy = b.y - a.y
    return Math.hypot(dx, dy)
}

function normalize(dx: number, dy: number) {
    const len = Math.hypot(dx, dy)
    if (len === 0) return { x: 0, y: 0, len: 0 }
    return { x: dx / len, y: dy / len, len }
}

function roundedPolygonPath(points: Point[], radius: number) {
    const pts = (points || []).filter(Boolean)
    const n = pts.length
    if (n < 3) {
        return "M 0 0 L 100 0 L 100 100 L 0 100 Z"
    }

    const rBase = Math.max(0, radius)
    if (rBase <= 0) {
        return `M ${pts[0].x} ${pts[0].y} ${pts
            .slice(1)
            .map((p) => `L ${p.x} ${p.y}`)
            .join(" ")
            .trim()} Z`
    }

    const start: Point[] = new Array(n)
    const end: Point[] = new Array(n)

    for (let i = 0; i < n; i++) {
        const prev = pts[(i - 1 + n) % n]
        const curr = pts[i]
        const next = pts[(i + 1) % n]

        const inVec = normalize(curr.x - prev.x, curr.y - prev.y)
        const outVec = normalize(next.x - curr.x, next.y - curr.y)

        const lenIn = dist(prev, curr)
        const lenOut = dist(curr, next)

        const r = Math.min(rBase, lenIn / 2, lenOut / 2)

        start[i] = { x: curr.x - inVec.x * r, y: curr.y - inVec.y * r }
        end[i] = { x: curr.x + outVec.x * r, y: curr.y + outVec.y * r }
    }

    let d = `M ${end[n - 1].x} ${end[n - 1].y}`
    for (let i = 0; i < n; i++) {
        const curr = pts[i]
        d += ` L ${start[i].x} ${start[i].y}`
        d += ` Q ${curr.x} ${curr.y} ${end[i].x} ${end[i].y}`
    }
    d += " Z"
    return d
}

export default function WaveHoverAnimation(props: RollingTextProps) {
    const {
        text,
        transition,
        stagger,
        reverse,
        font,
        color,
        hoverColor,
        background,
        shape,
        radius,
        textTransform,
        padding,
        gap,
        textAlign,
        style,
    } = props

    const [isHovered, setIsHovered] = useState(false)
    const clipId = useId()
    const containerRef = useRef<HTMLDivElement | null>(null)
    const [measuredSize, setMeasuredSize] = useState<{ w: number; h: number }>({ w: 0, h: 0 })

    const resolvedTextAlign = textAlign ?? font?.textAlign ?? "center"

    const fontSizeStr = font?.fontSize ?? "16px"
    const rawLineHeight = font?.lineHeight
    const fontFamily = font?.fontFamily ?? "Inter"
    const fontSizeNum = parseInt(String(fontSizeStr), 10) || 16

    let absoluteLineHeightPx: number | string
    if (typeof rawLineHeight === "number") {
        absoluteLineHeightPx = fontSizeNum * rawLineHeight
    } else if (typeof rawLineHeight === "string" && rawLineHeight.includes("em")) {
        const emValue = parseFloat(rawLineHeight) || 1.2
        absoluteLineHeightPx = fontSizeNum * emValue
    } else if (typeof rawLineHeight === "string") {
        const pxValue = parseFloat(rawLineHeight)
        absoluteLineHeightPx = Number.isNaN(pxValue) ? rawLineHeight : `${pxValue}px`
    } else {
        absoluteLineHeightPx = fontSizeNum * 1.2
    }

    const absoluteLineHeightStr =
        typeof absoluteLineHeightPx === "number" ? `${absoluteLineHeightPx}px` : absoluteLineHeightPx

    const yOffset = `-${absoluteLineHeightStr}`

    const innerStyle: CSSProperties = {
        boxSizing: "border-box",
        margin: 0,
        padding: "0 0.08em 0 0",
        display: "flex",
        overflowX: "visible",
        overflowY: "hidden",
        justifyContent: resolvedTextAlign === "left" ? "flex-start" : resolvedTextAlign === "right" ? "flex-end" : "center",
        alignItems: "center",
        fontFamily,
        fontSize: fontSizeStr,
        textTransform,
        userSelect: "text",
        position: "relative",
        height: absoluteLineHeightStr,
        lineHeight: absoluteLineHeightStr,
    }

    const innerFlexStyle: CSSProperties = {
        display: "flex",
        justifyContent: resolvedTextAlign === "left" ? "flex-start" : resolvedTextAlign === "right" ? "flex-end" : "center",
        width: "max-content",
    }

    const charWrapperVariants = {
        initial: { y: "0%" },
        hover: { y: `calc(-100% - ${gap}px)` },
    }

    const baseDuration = typeof transition?.duration === "number" ? transition.duration : 0.5
    const staggerFactor = stagger / 100

    const bgEnabled = background?.enabled ?? true
    const shapeEnabled = shape?.enabled ?? false

    useEffect(() => {
        if (typeof window === "undefined") return
        const el = containerRef.current
        if (!el || typeof ResizeObserver === "undefined") return
        const ro = new ResizeObserver((entries) => {
            const r = entries[0]?.contentRect
            if (!r) return
            startTransition(() => setMeasuredSize({ w: r.width, h: r.height }))
        })
        ro.observe(el)
        return () => ro.disconnect()
    }, [])

    const wrapperTransitionParts: string[] = []
    if (bgEnabled) {
        const t = Math.max(0, background?.hoverTransition ?? 0)
        wrapperTransitionParts.push(`background-color ${t}s ease`, `border-radius ${t}s ease`)
    }
    if (shapeEnabled) {
        const t = Math.max(0, shape?.transition ?? 0)
        wrapperTransitionParts.push(`clip-path ${t}s ease`)
    }

    const shapeMode = shape?.mode ?? "string"
    const activePointsFromMode = useMemo(() => {
        if (!shapeEnabled) return [] as Point[]
        const useHover = isHovered
        if (shapeMode === "points") {
            const pts = useHover ? shape?.hoverPoints : shape?.points
            return (pts || []).map((p) => ({ x: clamp(p?.x ?? 0, 0, 100), y: clamp(p?.y ?? 0, 0, 100) }))
        }
        const str = useHover ? shape?.hoverPolygon || shape?.polygon : shape?.polygon
        return parsePolygonToPoints(str || "")
    }, [shapeEnabled, isHovered, shapeMode, shape?.polygon, shape?.hoverPolygon, shape?.points, shape?.hoverPoints])

    const activePolygonString = useMemo(() => {
        if (!shapeEnabled) return undefined
        if (shapeMode === "points") return pointsToPolygonString(activePointsFromMode)
        return isHovered ? shape?.hoverPolygon || shape?.polygon : shape?.polygon
    }, [shapeEnabled, shapeMode, activePointsFromMode, isHovered, shape?.hoverPolygon, shape?.polygon])

    const shouldUseRounded = !!(shapeEnabled && shape?.roundedCorners)

    const cornerRadiusUnits = useMemo(() => {
        if (!shouldUseRounded) return 0
        const px = clamp(shape?.cornerRadius ?? 20, 0, 100)
        const minDim = Math.max(1, Math.min(measuredSize.w || 0, measuredSize.h || 0))
        if (!minDim || !Number.isFinite(minDim)) return 0
        // viewBox is 0..100; map px radius onto min dimension
        return clamp((px / minDim) * 100, 0, 50)
    }, [measuredSize.w, measuredSize.h, shape?.cornerRadius, shouldUseRounded])

    const activePathD = useMemo(() => {
        return roundedPolygonPath(activePointsFromMode, cornerRadiusUnits)
    }, [activePointsFromMode, cornerRadiusUnits])

    const wrapperStyle: CSSProperties = {
        position: "relative",
        display: "inline-block",
        verticalAlign: "top",
        lineHeight: 0,
        padding,
        backgroundColor: bgEnabled
            ? isHovered
                ? background.hoverBackgroundColor
                : background.backgroundColor
            : "transparent",
        transition: wrapperTransitionParts.length > 0 ? wrapperTransitionParts.join(", ") : "none",
        borderRadius: bgEnabled ? (isHovered ? background.hoverRadius || radius : radius) : radius,
        clipPath: !shouldUseRounded
            ? shapeEnabled
                ? (activePolygonString as any)
                : undefined
            : undefined,
        overflow: "hidden",
        WebkitTapHighlightColor: "transparent",
        ...style,
    }

    return (
        <div
            ref={containerRef as any}
            style={{
                ...wrapperStyle,
                color: "inherit",
                textDecoration: "none",
                cursor: "default",
                pointerEvents: "auto",
            }}
            onMouseEnter={() => startTransition(() => setIsHovered(true))}
            onMouseLeave={() => startTransition(() => setIsHovered(false))}
        >
            {shouldUseRounded && shapeEnabled && (
                <svg
                    width="100%"
                    height="100%"
                    viewBox="0 0 100 100"
                    preserveAspectRatio="none"
                    style={{ position: "absolute", inset: 0, width: "100%", height: "100%", pointerEvents: "none" }}
                    aria-hidden="true"
                >
                    <defs>
                        <clipPath id={clipId} clipPathUnits="userSpaceOnUse">
                            <motion.path
                                d={activePathD}
                                animate={{ d: activePathD }}
                                transition={{ duration: Math.max(0, shape?.transition ?? 0), ease: "easeInOut" }}
                            />
                        </clipPath>
                    </defs>
                </svg>
            )}

            <div
                style={{
                    position: "relative",
                    width: "100%",
                    height: "100%",
                    clipPath: shouldUseRounded && shapeEnabled ? `url(#${clipId})` : undefined,
                }}
            >
                <div style={{ ...innerStyle, position: "relative", zIndex: 1 }}>
                    <div style={innerFlexStyle}>
                        {[...text].map((str, index) => {
                            const charIndex = reverse ? text.length - 1 - index : index
                            const delay =
                                text.length > 0 ? (baseDuration / text.length) * charIndex * staggerFactor : 0

                            const charWrapperStyle: CSSProperties = {
                                display: "inline-flex",
                                flexDirection: "column",
                                alignItems: "center",
                                height: absoluteLineHeightStr,
                            }

                            const charStyle: CSSProperties = {
                                display: "block",
                                whiteSpace: "pre",
                                ...font,
                                lineHeight: absoluteLineHeightStr,
                            }

                            return (
                                <motion.div
                                    key={index}
                                    variants={charWrapperVariants}
                                    initial="initial"
                                    animate={isHovered ? "hover" : "initial"}
                                    transition={{
                                        ...transition,
                                        delay,
                                    }}
                                    style={charWrapperStyle}
                                >
                                    <span style={{ ...charStyle, color }}>{str === " " ? "\u00A0" : str}</span>
                                    <span style={{ ...charStyle, color: hoverColor, marginTop: `${gap}px` }}>
                                        {str === " " ? "\u00A0" : str}
                                    </span>
                                </motion.div>
                            )
                        })}
                    </div>
                </div>
            </div>
        </div>
    )
}

WaveHoverAnimation.displayName = "Wave Hover Animation"

